// Each source returns a different shape. Flatten both into one common record
// { source, metric, value } so everything downstream is shape-agnostic.
const out = [];

for (const item of $input.all()) {
  const d = item.json;

  if (d.stargazers_count !== undefined) {
    out.push({ json: { source: 'github', metric: 'stars',       value: d.stargazers_count } });
    out.push({ json: { source: 'github', metric: 'forks',       value: d.forks_count } });
    out.push({ json: { source: 'github', metric: 'open_issues', value: d.open_issues_count } });
  }

  if (d.bitcoin !== undefined) {
    out.push({ json: { source: 'coingecko', metric: 'btc_usd',     value: d.bitcoin.usd } });
    out.push({ json: { source: 'coingecko', metric: 'btc_vol_24h', value: Math.round(d.bitcoin.usd_24h_vol) } });
  }
}

if (out.length === 0) {
  throw new Error('No recognised source payload — both upstream APIs changed shape or failed.');
}

return out;

// Absolutes are noise; deltas are signal. Keep the previous run in workflow
// static data and report the change, not the number.
const store = $getWorkflowStaticData('global');
const prev  = store.lastRun || {};
const now   = {};
const out   = [];

for (const item of $input.all()) {
  const { source, metric, value } = item.json;
  const key = `${source}.${metric}`;
  now[key] = value;

  const before = prev[key];
  const delta  = before === undefined ? null : value - before;
  const pct    = (before === undefined || before === 0)
    ? null
    : Number(((delta / before) * 100).toFixed(2));

  out.push({ json: { source, metric, value, previous: before ?? null, delta, pct_change: pct } });
}

store.lastRun = now;
return out;

// Collapse every metric row into one plain-text block for the model.
const lines = $input.all().map((i) => {
  const j = i.json;
  const change = j.delta === null
    ? 'first run — no baseline yet'
    : `${j.delta >= 0 ? '+' : ''}${j.delta} (${j.pct_change}%)`;
  return `${j.source} ${j.metric}: ${j.value} — ${change}`;
}).join('\n');

return [{ json: { lines } }];
